from __future__ import annotations

from fastapi.responses import HTMLResponse


def analysis_page() -> HTMLResponse:
    return HTMLResponse(
        r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Nmap Terrain Analyzer · Analyze Results</title>
  <style>
    :root{color-scheme:dark;--bg:#091016;--panel:#111c25;--line:#263f49;--text:#edf6fb;--muted:#9eb0b8;--accent:#53d1b6;--blue:#64a9ff;--good:#61d095;--warn:#ffc66d;--bad:#ff837a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#102c35,#091016 44%);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}header,main{max-width:1180px;margin:auto}header{padding:26px 0 20px;border-bottom:1px solid var(--line)}h1{margin:0 0 4px;font-size:29px}h2{margin:0 0 9px;font-size:19px}h3{margin:20px 0 8px}.sub,.hint,.meta,.empty{color:var(--muted)}.eyebrow{color:var(--accent);font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:11px}.nav{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.nav a{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:9px 13px;text-decoration:none;font-weight:700}.nav a.active{background:var(--accent);border-color:var(--accent);color:#07171b}main{padding:24px 0 60px}.panel{background:rgba(17,28,37,.95);border:1px solid var(--line);border-radius:13px;padding:20px;box-shadow:0 12px 38px #0004;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1.4fr;gap:18px;align-items:start}.actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin-top:13px}button,.button-link{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:9px 12px;font:inherit;font-weight:750;cursor:pointer;text-decoration:none;display:inline-block}button.secondary,.button-link.secondary{background:transparent;border-color:#49617d}button:disabled{opacity:.5;cursor:not-allowed}input,select{width:100%;background:#0b141b;border:1px solid #344754;color:var(--text);border-radius:8px;padding:10px 11px;font:inherit}label{display:block;color:#bed0da;font-size:12px;font-weight:700;margin:5px 0}.status{min-height:23px;margin-top:10px;color:var(--muted)}.status.good{color:var(--good)}.status.bad{color:var(--bad)}.status.warn{color:var(--warn)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:14px 0}.card{padding:12px;background:#0b171f;border:1px solid var(--line);border-radius:9px}.card b{display:block;font-size:22px;color:var(--blue)}.coverage{padding:13px;background:#0b171f;border:1px solid #315264;border-radius:9px;margin:12px 0}.filterbar{display:grid;grid-template-columns:2fr 1fr;gap:12px;margin:18px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.05em}td{font-size:12px}.history-table{min-width:800px}.port-chip{display:block;padding:5px 7px;margin-bottom:4px;border-left:3px solid transparent;border-radius:5px}.port-chip.outlier{background:#4a3218;border-left-color:var(--warn);color:#ffe1ad}.outlier-tag{display:inline-block;margin-left:7px;padding:2px 5px;border-radius:99px;background:var(--warn);color:#291906;font-size:10px;font-weight:900;text-transform:uppercase}.group-label{color:var(--blue);font-weight:700}.outlier-group{margin:10px 0;padding:14px;background:#0b171f;border:1px solid var(--line);border-radius:9px}.result-box{margin-top:12px;padding:12px;background:#0b171f;border:1px solid var(--line);border-radius:9px}.result-box:empty{display:none}.comparison-host{margin:9px 0;border:1px solid #315264;border-radius:9px;background:#0d1820}.comparison-host summary{cursor:pointer;padding:10px 12px;font-weight:750;color:#dcecf5}.comparison-body{padding:0 12px 12px}.delta-before{color:#ffb6ae}.delta-after{color:#9ce5ba}.evidence-links{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.evidence-links a{color:#9cd4ff}.comparison-table{min-width:660px}code{color:#9cd4ff}.hidden{display:none!important}@media(max-width:1200px){header,main{padding-left:4vw;padding-right:4vw}}@media(max-width:820px){.grid,.filterbar{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}}
    .previous-scans-panel{height:560px;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}.history-table th{position:sticky;top:0;z-index:2;background:#111c25}@media(max-width:820px){.previous-scans-panel{height:min(560px,70vh)}}
    header{position:sticky;top:0;z-index:100;padding-top:16px;padding-bottom:14px;background:rgba(9,16,22,.96);backdrop-filter:blur(14px);box-shadow:0 9px 24px #0006}header h1{font-size:26px}.nav{margin-top:12px}
    .quality-warning{margin:12px 0;padding:13px 15px;border:1px solid #b9862d;border-radius:9px;background:#2b2416;color:#ffe3a8}.quality-warning strong{display:block;margin-bottom:5px;color:var(--warn)}.quality-warning ul{margin:6px 0 0;padding-left:20px}.analysis-tabs{display:flex;gap:8px;margin-bottom:16px}.analysis-tabs a{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:7px 11px;text-decoration:none;font-weight:700}.analysis-tabs a.active{background:var(--accent);border-color:var(--accent);color:#07171b}
  </style>
  <style>.mac-provenance{display:block;margin-top:4px;color:#9cd4ff;font-size:11px}.mac-provenance.indirect{color:#ffe3a8}.mac-provenance a{color:inherit}.mac-provenance-icon{display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;margin-right:3px;border:1px solid currentColor;border-radius:50%;font-size:10px;font-weight:900}</style>
</head>
<body>
  <header><div class="eyebrow">One analysis pipeline</div><h1>Analyze Nmap Results</h1><p class="sub">New uploads and historical scans use the same complete analysis view.</p><nav class="nav" aria-label="Primary"><a href="/scans">Nmap</a><a href="/device-config">Device</a><a class="active" href="/analysis" aria-current="page">Analyze</a><a href="/hunting">Hunt</a><a href="/network-map">Map</a></nav></header>
  <main>
    <nav class="analysis-tabs" aria-label="Analysis views"><a class="active" href="/analysis" aria-current="page">Nmap Results</a><a href="/device-analysis">Network Device Analysis</a></nav>
    <div class="grid">
      <section class="panel"><h2>Import Nmap XML</h2><form id="xmlForm"><label for="xmlFile">Nmap XML result</label><input id="xmlFile" type="file" accept=".xml,text/xml,application/xml" required><p class="hint">The original file and SHA-256 hash are retained.</p><div class="actions"><button type="submit">Import &amp; analyze</button></div><div id="xmlStatus" class="status" role="status"></div></form></section>
      <section class="panel previous-scans-panel"><div class="actions" style="justify-content:space-between;margin-top:0"><div><h2>Previous scans</h2><p class="hint">Automated runs use clear name, schedule, time, scope, and profile labels. Scroll within this window for older scans; select two completed runs to compare.</p></div><button id="historyRefresh" class="secondary">Refresh</button></div><div id="historyStatus" class="status"></div><h3>Automated scans</h3><div id="automatedHistory" class="meta">Loading…</div><div class="actions"><button id="compareRuns" disabled>Compare selected automated scans</button></div><div id="runCompareResult" class="result-box"></div><h3>Uploaded XML</h3><div id="history" class="meta">Loading…</div><div class="actions"><button id="compare" disabled>Compare selected uploads</button></div><div id="compareResult" class="result-box"></div></section>
    </div>
    <section id="analysisPanel" class="panel hidden"><div id="analysisTitle"></div><div id="analysisWarnings"></div><div id="results"></div><div id="autoCompareResult" class="result-box"></div></section>
  </main>
<script>
const $=id=>document.getElementById(id),qa=s=>[...document.querySelectorAll(s)],esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),csvCell=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
let historyItems=[],automatedItems=[],currentAnalysis=null,currentLabel='NCT-results-export';
function setStatus(id,message,kind=''){const node=$(id);node.textContent=message;node.className='status '+kind}
function decorateMacEvidence(){for(const row of qa('.host-row')){const host=currentAnalysis?.hosts?.[Number(row.dataset.index)],cell=row.children[2];if(!host?.mac_provenance||!cell||cell.querySelector('[data-mac-provenance]'))continue;const p=host.mac_provenance,note=document.createElement('span'),title=[p.origin,p.source_label,p.timestamp,p.detail].filter(Boolean).join(' · '),link=p.source_url?` · <a href="${esc(p.source_url)}" target="_blank" rel="noopener">source</a>`:'';note.dataset.macProvenance='true';note.className=`mac-provenance${p.indirect?' indirect':''}`;note.title=title;note.innerHTML=`<span class="mac-provenance-icon">i</span>${esc(p.indirect?'correlated by IP':'direct Nmap')}${link}`;cell.append(note)}}
const macEvidenceObserver=new MutationObserver(decorateMacEvidence);macEvidenceObserver.observe($('results'),{childList:true,subtree:true});
function protocolLabel(coverage){return(coverage?.protocols||[]).join(' + ')||'Not recorded'}
function coverageText(coverage){if(!coverage)return'Coverage metadata unavailable';const scans=(coverage.scan_types||[]).map(item=>`${item.protocol||'?'} ${item.service_count||0} services`).join(' · '),path=coverage.traceroute?' · traceroute paths collected':'';return `${protocolLabel(coverage)}${scans?' · '+scans:''} · DNS lookups ${coverage.dns_resolution_disabled?'disabled (-n)':'not confirmed'}${path}`}
function renderAnalysisWarnings(analysis){const warnings=analysis?.warnings||[];$('analysisWarnings').innerHTML=warnings.length?`<div class="quality-warning" role="alert"><strong>Analysis cautions</strong><ul>${warnings.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}
function downloadCsv(filename,header,records){const csv=[header,...records].map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n',blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();URL.revokeObjectURL(link.href)}
function exportHosts(){const hosts=qa('.host-row').filter(row=>row.style.display!=='none').map(row=>currentAnalysis.hosts[Number(row.dataset.index)]),header=['IP','Hostname','Host state','MAC','MAC vendor','Detected OS','OS family','OS generation','OS role group','Classification basis','Outlying ports','Open services'],records=hosts.map(h=>[h.ip,h.hostname,h.state,h.mac,h.vendor,h.os,h.os_family,h.os_generation,h.os_group,h.classification_basis,(h.ports||[]).filter(p=>p.outlier).map(p=>`${p.port}/${p.protocol}`).join('; '),(h.ports||[]).map(p=>`${p.port}/${p.protocol} ${p.service||''}${p.product?' '+p.product:''}${p.version?' '+p.version:''}`).join('; ')]);downloadCsv(`${currentLabel}-hosts.csv`,header,records)}
function exportPorts(){const visible=new Set(qa('.host-row').filter(row=>row.style.display!=='none').map(row=>Number(row.dataset.index))),header=['IP','Hostname','Host state','MAC','MAC vendor','Protocol','Port','Port state','Reason','Service','Product','Version','Detected OS','OS role group','Outlier'],records=[];(currentAnalysis.hosts||[]).forEach((h,index)=>{if(!visible.has(index))return;(h.ports||[]).forEach(p=>records.push([h.ip,h.hostname,h.state,h.mac,h.vendor,p.protocol,p.port,p.state||'open',p.reason,p.service,p.product,p.version,h.os,h.os_group,p.outlier?'yes':'no']))});downloadCsv(`${currentLabel}-ports.csv`,header,records)}
function compactExportLabel(label,identifier=''){const clean=String(label||'results').replace(/\.[A-Za-z0-9]{1,5}$/,'').replace(/[^A-Za-z0-9._-]+/g,'-').replace(/^[-._]+|[-._]+$/g,'').slice(0,36)||'results',shortId=String(identifier||'export').replace(/[^A-Za-z0-9]+/g,'').slice(0,8)||'export';return`NCT-${clean}-${shortId}`}
function renderAnalysis(a,context={}){currentAnalysis=a;currentLabel=compactExportLabel(context.display_name||context.filename,context.identifier);$('analysisPanel').classList.remove('hidden');$('autoCompareResult').innerHTML='';$('analysisTitle').innerHTML=`<h2>${esc(context.display_name||context.filename||'Nmap analysis')}</h2><p class="meta">${esc(context.subtitle||'Complete retained analysis')}</p>`;const outlierTotal=(a.os_groups||[]).reduce((n,g)=>n+(g.outlying_ports||[]).length,0),options=(a.os_groups||[]).map(g=>`<option value="${esc(g.name)}">${esc(g.name)} (${g.host_count})</option>`).join(''),groups=(a.os_groups||[]).map(g=>`<section class="outlier-group" data-outlier-group="${esc(g.name)}"><h3>${esc(g.name)} · ${g.host_count} host${g.host_count===1?'':'s'}</h3>${g.host_count<2?'<p class="empty">At least two hosts are needed to identify outliers.</p>':(g.outlying_ports||[]).length?`<div class="table-wrap"><table><thead><tr><th>Outlying port</th><th>Service</th><th>Seen on</th><th>Affected hosts</th></tr></thead><tbody>${g.outlying_ports.map(p=>`<tr><td>${esc(p.port)}/${esc(p.protocol)}</td><td>${esc(p.service)}${p.product?' · '+esc(p.product):''}</td><td>${p.host_count} of ${p.group_host_count} (${p.prevalence_percent}%)</td><td>${p.hosts.map(esc).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No statistical port outliers in this group.</p>'}</section>`).join(''),rows=(a.hosts||[]).map((h,index)=>{const search=[h.ip,h.hostname,h.mac,h.vendor,h.os,h.os_family,h.os_generation,h.device_type,h.os_group,...(h.ports||[]).flatMap(p=>[p.port,p.protocol,p.service,p.product,p.version])].join(' ').toLowerCase(),ports=(h.ports||[]).map(p=>`<span class="port-chip${p.outlier?' outlier':''}">${esc(p.port)}/${esc(p.protocol)} ${esc(p.service)}${p.product?' · '+esc(p.product):''}${p.version?' '+esc(p.version):''}${p.outlier?'<span class="outlier-tag">Outlier</span>':''}</span>`).join('')||'None reported';return`<tr class="host-row" data-index="${index}" data-group="${esc(h.os_group)}" data-search="${esc(search)}"><td><strong>${esc(h.ip||'—')}</strong><br><span class="meta">${esc(h.hostname||'')}</span></td><td>${esc(h.state)}</td><td>${esc(h.mac||'—')}<br><span class="meta">${esc(h.vendor||'')}</span></td><td>${esc(h.os||'Unknown')}<br><span class="group-label">${esc(h.os_group)}</span><br><span class="hint">${esc(h.classification_basis)}</span></td><td>${ports}</td></tr>`}).join('');$('results').innerHTML=`<div class="cards"><div class="card"><b id="visibleHosts">${a.host_count||0}</b>matching hosts</div><div class="card"><b>${a.up_count||0}</b>hosts up</div><div class="card"><b>${a.mac_count||0}</b>MAC addresses</div><div class="card"><b>${outlierTotal}</b>outlying ports</div></div><div class="coverage"><strong>Scan coverage</strong><br>${esc(coverageText(a.coverage))}${a.started?`<br><span class="meta">Started ${esc(a.started)}${a.finished?' · Finished '+esc(a.finished):''}</span>`:''}</div><div class="filterbar"><div><label for="hostSearch">Search results</label><input id="hostSearch" type="search" placeholder="IP, hostname, MAC, OS, service, product, or port"></div><div><label for="osFilter">OS / role group</label><select id="osFilter"><option value="">All OS groups</option>${options}</select></div></div><div class="actions"><button id="exportHosts" class="secondary">Export host summary CSV</button><button id="exportPorts">Export port-level CSV</button></div><h3>Outlying ports by OS type</h3><div id="outlierGroups">${groups||'<p class="empty">No OS groups were detected.</p>'}</div><h3>Host inventory</h3><div class="table-wrap"><table><thead><tr><th>IP / hostname</th><th>State</th><th>MAC / vendor</th><th>OS / peer group</th><th>Open services</th></tr></thead><tbody>${rows}</tbody></table></div>`;const apply=()=>{const term=$('hostSearch').value.trim().toLowerCase(),group=$('osFilter').value;let visible=0;qa('.host-row').forEach(row=>{const show=(!group||row.dataset.group===group)&&(!term||row.dataset.search.includes(term));row.style.display=show?'':'none';if(show)visible++});$('visibleHosts').textContent=visible;qa('.outlier-group').forEach(card=>card.style.display=(!group||card.dataset.outlierGroup===group)?'':'none')};$('hostSearch').oninput=apply;$('osFilter').onchange=apply;$('exportHosts').onclick=exportHosts;$('exportPorts').onclick=exportPorts;$('analysisPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function renderAutomatedHistory(){if(!automatedItems.length){$('automatedHistory').innerHTML='<div class="empty">No completed automated scans with retained XML are available.</div>';$('compareRuns').disabled=true;return}$('automatedHistory').innerHTML=`<div class="table-wrap"><table class="history-table"><thead><tr><th>Select</th><th>Comparison name</th><th>Scope</th><th>Profile</th><th>Actions</th></tr></thead><tbody>${automatedItems.map(item=>`<tr><td><input type="checkbox" data-run-select="${esc(item.selection_run_id)}" aria-label="Select ${esc(item.comparison_name)}"></td><td><strong>${esc(item.display_name)}</strong><br><span class="meta">${item.scheduled?'Scheduled':'Manual'} · completed ${esc(item.completed_at||item.created_at||'—')} · ${Number(item.chunk_count||1)} chunk${Number(item.chunk_count||1)===1?'':'s'}</span></td><td>${esc((item.scope?.targets||[]).join(', ')||'Unavailable')}<br><span class="meta">${Number(item.scope?.address_count||0).toLocaleString()} effective addresses</span></td><td>${esc(item.profile||'Run-specific')} v${esc(item.profile_version||'—')}<br><span class="meta">${esc(protocolLabel(item.coverage))}</span></td><td><button data-run-open="${esc(item.selection_run_id)}">Open &amp; analyze</button> <a class="button-link secondary" href="/hunting?run=${encodeURIComponent(item.selection_run_id)}">Hunt</a></td></tr>`).join('')}</tbody></table></div>`;qa('[data-run-select]').forEach(box=>box.onchange=()=>{$('compareRuns').disabled=qa('[data-run-select]:checked').length!==2});qa('[data-run-open]').forEach(button=>button.onclick=()=>openRun(button.dataset.runOpen))}
function renderHistory(){if(!historyItems.length){$('history').innerHTML='<div class="empty">No imported Nmap scans have been retained.</div>';$('compare').disabled=true;return}$('history').innerHTML=`<div class="table-wrap"><table class="history-table"><thead><tr><th>Select</th><th>Scan</th><th>Imported</th><th>Coverage</th><th>Identity</th><th>Actions</th></tr></thead><tbody>${historyItems.map(item=>`<tr><td><input type="checkbox" data-select="${esc(item.sha256)}" aria-label="Select ${esc(item.display_name||item.filename)}"></td><td><strong>${esc(item.display_name||item.filename)}</strong><br><span class="meta">${esc(item.filename)} · ${esc(item.sha256.slice(0,12))}</span></td><td>${esc(item.imported_at)}</td><td>${esc(coverageText(item.summary?.coverage))}<br><span class="meta">${Number(item.summary?.up_count||0)} up / ${Number(item.summary?.host_count||0)} parsed</span></td><td>${Number(item.summary?.mac_count||0)} MAC addresses<br>${Number(item.summary?.os_group_count||0)} OS groups</td><td><button data-open="${esc(item.sha256)}">Open &amp; analyze</button> <a class="button-link secondary" href="/api/imports/${encodeURIComponent(item.sha256)}/raw">Raw XML</a></td></tr>`).join('')}</tbody></table></div>`;qa('[data-select]').forEach(box=>box.onchange=()=>{$('compare').disabled=qa('[data-select]:checked').length!==2});qa('[data-open]').forEach(button=>button.onclick=()=>openHistory(button.dataset.open))}
async function loadHistory(){setStatus('historyStatus','Loading automated scans and uploaded XML…');try{const [importsResponse,runsResponse]=await Promise.all([fetch('/api/imports?limit=100'),fetch('/api/scan-comparisons/candidates')]),imports=await importsResponse.json(),runs=await runsResponse.json();if(!importsResponse.ok)throw new Error(imports.detail||'Upload history request failed');if(!runsResponse.ok)throw new Error(runs.detail||'Automated history request failed');historyItems=imports||[];automatedItems=runs||[];renderHistory();renderAutomatedHistory();setStatus('historyStatus',`${automatedItems.length} automated scan${automatedItems.length===1?'':'s'} · ${historyItems.length} uploaded scan${historyItems.length===1?'':'s'}`,'good')}catch(error){setStatus('historyStatus',error.message,'bad')}}
async function openHistory(sha){setStatus('historyStatus','Opening full analysis…');try{const r=await fetch(`/api/imports/${encodeURIComponent(sha)}`),item=await r.json();if(!r.ok)throw new Error(item.detail||'Analysis could not be opened');renderAnalysis(item.analysis||{},{display_name:item.display_name||item.filename,filename:item.filename,identifier:sha,subtitle:`Imported ${item.imported_at} · historical analysis`});renderAnalysisWarnings(item.analysis||{});setStatus('historyStatus','Historical scan opened in the full analysis view.','good')}catch(error){setStatus('historyStatus',error.message,'bad')}}
function comparisonHostName(host){return host.hostname||host.ip||host.key||'Unknown host'}
function comparisonValue(value){if(value===null||value===undefined||value==='')return'—';return typeof value==='object'?JSON.stringify(value):String(value)}
function portEvidence(port){return`${port.port||'?'} / ${port.protocol||'?'} · ${port.state||'unknown'} · ${port.service||'unknown'}${port.product?' · '+port.product:''}${port.version?' '+port.version:''}`}
function pathEvidence(value){if(!value)return'Not collected';const hops=value.hops||[];return hops.length?hops.map(hop=>`TTL ${hop.ttl}: ${hop.ip}${hop.hostname?' ('+hop.hostname+')':''}`).join(' → '):'No hops reported'}
function evidenceLinks(evidence){const sources=[...(evidence?.before?.sources||[]),...(evidence?.after?.sources||[])],seen=new Set(),links=sources.filter(source=>source?.url&&!seen.has(source.url)&&seen.add(source.url)).map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.label||'Evidence')}</a>`);return links.length?`<div class="evidence-links"><span class="meta">Evidence:</span>${links.join('')}</div>`:''}
function renderHostSnapshot(host,label){const ports=host.ports||[];return`<details class="comparison-host"><summary>${esc(comparisonHostName(host))}${host.ip?` · <code>${esc(host.ip)}</code>`:''}</summary><div class="comparison-body"><p>${esc(label)} · ${esc(host.state||'state unknown')}${host.mac?` · MAC ${esc(host.mac)}`:''}${host.os?` · ${esc(host.os)}`:''}</p>${ports.length?`<ul>${ports.map(port=>`<li>${esc(portEvidence(port))}</li>`).join('')}</ul>`:'<p class="meta">No individual port observations retained.</p>'}${evidenceLinks(host.evidence?{before:host.evidence,after:null}:null)}</div></details>`}
function renderChangedHost(host){const serviceRows=(host.service_changes||[]).map(change=>`<tr><td>${esc(change.port)}/${esc(change.protocol)}</td><td class="delta-before">${esc(portEvidence(change.before||{}))}</td><td class="delta-after">${esc(portEvidence(change.after||{}))}</td><td>${esc((change.changed_fields||[]).join(', '))}</td></tr>`).join(''),identityRows=Object.entries(host.identity_changes||{}).map(([field,change])=>`<tr><td>${esc(field)}</td><td class="delta-before">${esc(comparisonValue(change.before))}</td><td class="delta-after">${esc(comparisonValue(change.after))}</td></tr>`).join('');return`<details class="comparison-host" open><summary>${esc(comparisonHostName(host))} · ${(host.added_ports||[]).length} added · ${(host.removed_ports||[]).length} removed · ${(host.port_state_changes||[]).length} state · ${Object.keys(host.identity_changes||{}).length} identity · ${host.route_change?'path changed':'path unchanged'}</summary><div class="comparison-body">${(host.added_ports||[]).length?`<h4>Newly observed ports</h4><ul class="delta-after">${host.added_ports.map(port=>`<li>${esc(portEvidence(port))}</li>`).join('')}</ul>`:''}${(host.removed_ports||[]).length?`<h4>No longer observed</h4><ul class="delta-before">${host.removed_ports.map(port=>`<li>${esc(portEvidence(port))}</li>`).join('')}</ul>`:''}${serviceRows?`<h4>Port state, service, product, or version changes</h4><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Port</th><th>Before</th><th>After</th><th>Changed fields</th></tr></thead><tbody>${serviceRows}</tbody></table></div>`:''}${identityRows?`<h4>Host identity changes</h4><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Field</th><th>Before</th><th>After</th></tr></thead><tbody>${identityRows}</tbody></table></div>`:''}${host.route_change?`<h4>Traceroute path change</h4><p class="delta-before"><strong>Before:</strong> ${esc(pathEvidence(host.route_change.before))}</p><p class="delta-after"><strong>After:</strong> ${esc(pathEvidence(host.route_change.after))}</p>`:''}${evidenceLinks(host.evidence)}</div></details>`}
function renderComparisonDetails(result,targetId,title){const target=$(targetId),summary=result.summary||{},warnings=result.coverage_warnings||[],before=result.before||result.baseline||{},after=result.after||result.current||{},warningHtml=warnings.length?`<div class="coverage"><strong>Coverage differences require caution</strong><ul>${warnings.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><span class="meta">Host presence is shown, but port and identity deltas are reliable only where the two scans have overlapping coverage.</span></div>`:'<p class="status good">Targets, protocols, and retained coverage are compatible.</p>';target.innerHTML=`<h3>${esc(title)}</h3><p class="meta">${esc(before.comparison_name||before.display_name||before.filename||'Earlier scan')} → ${esc(after.comparison_name||after.display_name||after.filename||'Later scan')}</p>${evidenceLinks(result.evidence)}${warningHtml}<div class="cards"><div class="card"><b>${summary.hosts_added||0}</b>hosts added</div><div class="card"><b>${summary.hosts_removed||0}</b>hosts removed</div><div class="card"><b>${summary.hosts_changed||0}</b>hosts changed</div><div class="card"><b>${summary.ports_added||0}</b>ports added</div><div class="card"><b>${summary.ports_removed||0}</b>ports removed</div><div class="card"><b>${summary.port_state_changes||0}</b>state changes</div><div class="card"><b>${summary.identity_changes||0}</b>identity changes</div><div class="card"><b>${summary.route_changes||0}</b>path changes</div></div>${(result.hosts_added||[]).length?`<h3>New hosts</h3>${result.hosts_added.map(host=>renderHostSnapshot(host,'Present only in the later scan')).join('')}`:''}${(result.hosts_removed||[]).length?`<h3>Missing hosts</h3>${result.hosts_removed.map(host=>renderHostSnapshot(host,'Present only in the earlier scan')).join('')}`:''}${(result.hosts_changed||[]).length?`<h3>Affected hosts and evidence</h3>${result.hosts_changed.map(renderChangedHost).join('')}`:''}${!summary.hosts_added&&!summary.hosts_removed&&!summary.hosts_changed?'<p class="status good">No host, port, service, product, version, identity, MAC, OS, or path changes were detected.</p>':''}`;target.scrollIntoView({behavior:'smooth',block:'nearest'})}
function renderAutomaticComparison(result){const target=$('autoCompareResult');if(result.status!=='baseline_found'){target.innerHTML=`<h3>Automatic same-scope comparison</h3><p class="meta">${esc(result.message||'No compatible baseline is available.')}</p>`;return}renderComparisonDetails(result,'autoCompareResult','Automatic same-scope comparison')}
async function loadAutomaticComparison(runId){const target=$('autoCompareResult');target.innerHTML='<h3>Automatic same-scope comparison</h3><p class="meta">Finding the latest completed scan with the same effective target scope…</p>';try{const response=await fetch(`/api/scan-runs/${encodeURIComponent(runId)}/comparison`),result=await response.json();if(!response.ok)throw new Error(result.detail||'Automatic comparison failed');renderAutomaticComparison(result)}catch(error){target.innerHTML=`<h3>Automatic same-scope comparison</h3><p class="status bad">${esc(error.message)}</p>`}}
async function openRun(runId){setStatus('xmlStatus','Opening automated scan analysis…');try{const r=await fetch(`/api/scan-runs/${encodeURIComponent(runId)}/analysis`),item=await r.json();if(!r.ok)throw new Error(item.detail||'Run analysis could not be opened');renderAnalysis(item.analysis||{},{display_name:item.comparison_name||item.display_name,identifier:runId,subtitle:`Automated scan · ${item.metadata?.group?.chunk_count||1} chunk${Number(item.metadata?.group?.chunk_count||1)===1?'':'s'} · ${item.metadata?.profile||''} v${item.metadata?.profile_version||''}`});renderAnalysisWarnings(item.analysis||{});setStatus('xmlStatus','Automated scan opened in the full analysis view.','good');await loadAutomaticComparison(runId)}catch(error){setStatus('xmlStatus',error.message,'bad')}}
async function compare(){const selected=qa('[data-select]:checked').map(box=>box.dataset.select);if(selected.length!==2)return;const target=$('compareResult');target.innerHTML='<span class="meta">Comparing uploaded XML…</span>';try{const r=await fetch(`/api/imports/compare?first=${encodeURIComponent(selected[0])}&second=${encodeURIComponent(selected[1])}`),result=await r.json();if(!r.ok)throw new Error(result.detail||'Comparison failed');renderComparisonDetails(result,'compareResult','Uploaded XML comparison')}catch(error){target.innerHTML=`<span class="status bad">${esc(error.message)}</span>`}}
async function compareRuns(){const selected=qa('[data-run-select]:checked').map(box=>box.dataset.runSelect);if(selected.length!==2)return;const target=$('runCompareResult');target.innerHTML='<span class="meta">Comparing complete automated scan groups…</span>';try{const r=await fetch(`/api/scan-comparisons/compare?first=${encodeURIComponent(selected[0])}&second=${encodeURIComponent(selected[1])}`),result=await r.json();if(!r.ok)throw new Error(result.detail||'Automated comparison failed');renderComparisonDetails(result,'runCompareResult','Automated scan comparison')}catch(error){target.innerHTML=`<span class="status bad">${esc(error.message)}</span>`}}
$('xmlForm').onsubmit=async event=>{event.preventDefault();const file=$('xmlFile').files[0];if(!file)return;setStatus('xmlStatus','Preserving and analyzing the original XML…');try{const form=new FormData();form.append('file',file);const r=await fetch('/api/import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Import failed');renderAnalysis(data.analysis,{display_name:data.metadata?.display_name||file.name,filename:file.name,identifier:data.sha256,subtitle:`${data.duplicate?'Duplicate recognized':'Original preserved'} · SHA-256 ${data.sha256}`});renderAnalysisWarnings(data.analysis||{});setStatus('xmlStatus','Analysis complete.','good');await loadHistory()}catch(error){setStatus('xmlStatus',error.message,'bad')}};
$('historyRefresh').onclick=loadHistory;$('compare').onclick=compare;$('compareRuns').onclick=compareRuns;
function prepareRunComparison(runId){const box=qa('[data-run-select]').find(item=>item.dataset.runSelect===runId);if(!box)return;box.checked=true;$('compareRuns').disabled=true;setStatus('historyStatus','Starting comparison with this scan. Select one more automated scan, then choose Compare selected automated scans.','warn');box.closest('tr')?.scrollIntoView({behavior:'smooth',block:'nearest'})}
async function initializeAnalysisPage(){const params=new URLSearchParams(location.search),runId=params.get('run'),compareRunId=params.get('compare');await loadHistory();if(compareRunId)prepareRunComparison(compareRunId);if(runId)await openRun(runId)}
initializeAnalysisPage();
</script>
</body></html>'''
    )
